package dev.rag.knowledge;
import dev.rag.common.*;
import dev.rag.identity.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.Instant;

@Service
public class KnowledgeService {
 final Db db;final AccessPolicy access;final IdentityService identity;final TransactionTemplate tx;final PrivateArtifacts files;
 public KnowledgeService(Db db,AccessPolicy access,IdentityService identity,TransactionTemplate tx,PrivateArtifacts files){this.db=db;this.access=access;this.identity=identity;this.tx=tx;this.files=files;}
 public Map<String,Object> upload(Actor a,String kb,String documentId,String name,byte[] bytes,String key,Map<String,Object> config){access.requireAdmin(a);if(key==null||key.isBlank()||key.length()>80)throw IdentityService.invalid("需要最多80字符的 Idempotency-Key");InputValidation.validate(bytes,name);if(!access.canReadKb(a,kb))throw ApiException.missing();if(documentId!=null)access.requireDocument(a,documentId);byte[] requestHash=AccessPolicy.hash((kb+":"+documentId+":"+name+":"+HexFormat.of().formatHex(AccessPolicy.hash(bytes))+":"+Json.write(config)).getBytes(StandardCharsets.UTF_8));String scoped=a.userId()+":"+key;var existing=db.optional("SELECT * FROM job WHERE tenant_id=:t AND kind='INGEST' AND idempotency_key=:k",Db.params("t",a.tenantId(),"k",scoped));if(existing.isPresent()){if(!Arrays.equals((byte[])existing.get().get("request_hash"),requestHash))throw new ApiException(409,"IDEMPOTENCY_CONFLICT","相同键对应不同上传");return jobResult(a,existing.get());}
  String storage=files.save(a.tenantId(),bytes);try{return access.write(a,()->tx.execute(s->{String doc=documentId;if(doc==null){doc=Json.id();db.insert("document",Db.params("tenant_id",a.tenantId(),"id",doc,"kb_id",kb,"title",name));db.insert("document_grant",Db.params("tenant_id",a.tenantId(),"id",Json.id(),"document_id",doc,"principal_type","USER","user_id",a.userId()));}var current=db.one("SELECT * FROM document WHERE tenant_id=:t AND id=:d FOR UPDATE",Db.params("t",a.tenantId(),"d",doc));if(!current.get("status").equals("LIVE")||!current.get("kb_id").equals(kb))throw ApiException.missing();String payload=Json.write(validateConfig(config));byte[] configHash=AccessPolicy.hash(payload);var duplicate=db.optional("SELECT j.* FROM document_version v JOIN index_build b ON b.tenant_id=v.tenant_id AND b.version_id=v.id JOIN config_revision c ON c.tenant_id=b.tenant_id AND c.id=b.config_id JOIN job j ON j.tenant_id=b.tenant_id AND j.target_id=b.id AND j.kind='INGEST' WHERE v.tenant_id=:t AND v.document_id=:d AND v.source_hash=:h AND c.sha256=:ch ORDER BY v.version_no DESC LIMIT 1",Db.params("t",a.tenantId(),"d",doc,"h",AccessPolicy.hash(bytes),"ch",configHash));if(duplicate.isPresent()){files.delete(storage);return jobResult(a,duplicate.get());}String artifact=Json.id(),version=Json.id(),build=Json.id(),configId=Json.id();int number=((Number)db.one("SELECT COALESCE(MAX(version_no),0)+1 AS n FROM document_version WHERE tenant_id=:t AND document_id=:d",Db.params("t",a.tenantId(),"d",doc)).get("n")).intValue();db.insert("artifact",Db.params("tenant_id",a.tenantId(),"id",artifact,"document_id",doc,"kind","SOURCE","storage_key",storage,"sha256",AccessPolicy.hash(bytes),"size_bytes",bytes.length));db.insert("document_version",Db.params("tenant_id",a.tenantId(),"id",version,"document_id",doc,"version_no",number,"source_artifact_id",artifact,"source_hash",AccessPolicy.hash(bytes),"original_name",name,"media_type","application/octet-stream","created_by",a.userId()));db.insert("config_revision",Db.params("tenant_id",a.tenantId(),"id",configId,"kind","BUILD","name",build,"revision",1,"sha256",configHash,"payload",payload,"status","PUBLISHED"));db.insert("index_build",Db.params("tenant_id",a.tenantId(),"id",build,"document_id",doc,"version_id",version,"build_no",1,"config_id",configId,"status","QUEUED","capabilities","[]","fence",current.get("lifecycle_epoch")));String job=queue(a,"INGEST",build,scoped,requestHash,current.get("lifecycle_epoch"),"PARSING");identity.audit(a,"DOCUMENT_UPLOAD","DOCUMENT",doc);return Db.params("documentId",doc,"versionId",version,"buildId",build,"jobId",job,"status","QUEUED");}));}catch(RuntimeException e){files.delete(storage);throw e;}
 }
 static Map<String,Object> validateConfig(Map<String,Object> c){boolean embedding=Json.bool(c,"embedding",false),summary=Json.bool(c,"summary",false),questions=Json.bool(c,"questions",false);int child=Json.integer(c,"childCodePoints",900),parent=Json.integer(c,"parentCodePoints",3000);if(child<64||child>4000||parent<child||parent>12000)throw IdentityService.invalid("分块长度无效");return Map.of("embedding",embedding,"summary",summary,"questions",questions,"vision",Json.bool(c,"vision",false),"childCodePoints",child,"parentCodePoints",parent,"tokenizer","unicode-codepoint-estimate-v1");}
 public String queue(Actor a,String kind,String target,String key,byte[] hash,Object fence,String stage){String id=Json.id();db.insert("job",Db.params("tenant_id",a.tenantId(),"id",id,"kind",kind,"target_id",target,"requested_by",a.userId(),"idempotency_key",key,"request_hash",hash,"status","QUEUED","stage",stage,"available_at",Timestamp.from(Instant.now()),"fence",fence,"checkpoint","{}"));return id;}
 private Map<String,Object> jobResult(Actor a,Map<String,Object> j){var b=db.one("SELECT document_id,version_id FROM index_build WHERE tenant_id=:t AND id=:b",Db.params("t",a.tenantId(),"b",j.get("target_id")));return Db.params("documentId",b.get("document_id"),"versionId",b.get("version_id"),"buildId",j.get("target_id"),"jobId",j.get("id"),"status",j.get("status"));}
 public List<Map<String,Object>> list(Actor a,String kb,boolean admin,String status){if(admin)access.requireAdmin(a);var params=Db.params("t",a.tenantId(),"u",a.userId(),"kb",kb,"status",status==null?"LIVE":status);String where=admin?"d.tenant_id=:t AND d.status=:status":AccessPolicy.readable();if(kb!=null&&!kb.isBlank())where+=" AND d.kb_id=:kb";var rows=db.list("SELECT d.id,d.kb_id AS kbId,d.title,d.status,d.row_version AS rowVersion,d.active_build_id AS activeBuildId,(SELECT version_id FROM index_build b WHERE b.tenant_id=d.tenant_id AND b.id=d.active_build_id) AS activeVersionId FROM document d WHERE "+where+" ORDER BY d.created_at DESC LIMIT 100",params);for(var r:rows)if(!access.canReadDocument(a,r.get("id").toString())){r.remove("title");r.remove("activeBuildId");r.remove("activeVersionId");}return rows;}
 public Map<String,Object> get(Actor a,String id){return access.guard(a,List.of(id),()->db.one("SELECT id,kb_id AS kbId,title,status,row_version AS rowVersion,active_build_id AS activeBuildId FROM document WHERE tenant_id=:t AND id=:d",Db.params("t",a.tenantId(),"d",id)));}
 public Object preview(Actor a,String doc,String version){return access.guard(a,List.of(doc),()->{var v=db.one("SELECT id FROM document_version WHERE tenant_id=:t AND document_id=:d AND id=:v",Db.params("t",a.tenantId(),"d",doc,"v",version));return db.list("SELECT b.id AS buildId,b.status,b.quality_warnings AS warnings,u.id AS unitId,u.kind,u.text_content AS text,u.location,u.machine_generated AS machineGenerated,u.artifact_id AS artifactId FROM index_build b LEFT JOIN source_unit u ON u.tenant_id=b.tenant_id AND u.build_id=b.id WHERE b.tenant_id=:t AND b.document_id=:d AND b.version_id=:v ORDER BY b.build_no DESC,u.unit_key LIMIT 100",Db.params("t",a.tenantId(),"d",doc,"v",version));});}
 public Map<String,Object> lifecycle(Actor a,String doc,String action,long expected){access.requireAdmin(a);return access.write(a,()->tx.execute(s->{var d=db.one("SELECT * FROM document WHERE tenant_id=:t AND id=:d FOR UPDATE",Db.params("t",a.tenantId(),"d",doc));if(((Number)d.get("row_version")).longValue()!=expected)throw IdentityService.conflict();String state=d.get("status").toString();if(action.equals("trash")&&!state.equals("LIVE")||action.equals("restore")&&!state.equals("TRASHED")||action.equals("purge")&&!state.equals("TRASHED"))throw new ApiException(409,"INVALID_STATE","文档状态不允许此操作");long fence=((Number)d.get("lifecycle_epoch")).longValue()+1;String status=action.equals("trash")?"TRASHED":action.equals("purge")?"PURGE_PENDING":"TRASHED";db.exec("UPDATE document SET status=:s,lifecycle_epoch=:f,row_version=row_version+1,deleted_at=COALESCE(deleted_at,UTC_TIMESTAMP(6)) WHERE tenant_id=:t AND id=:d",Db.params("s",status,"f",fence,"t",a.tenantId(),"d",doc));identity.epoch(a);identity.audit(a,"DOCUMENT_"+action.toUpperCase(Locale.ROOT),"DOCUMENT",doc);if(action.equals("trash"))return Map.of("documentId",doc,"status",status);String kind=action.toUpperCase(Locale.ROOT);String job=queue(a,kind,doc,Json.id(),AccessPolicy.hash(doc+fence),fence,kind);if(kind.equals("PURGE"))db.insert("deletion_record",Db.params("tenant_id",a.tenantId(),"id",Json.id(),"document_id",doc,"origin_system","local","requested_by",a.userId(),"status","PENDING","domains_json","{}","backup_expiry_at",Timestamp.from(Instant.now().plusSeconds(7*86400))));return Map.of("documentId",doc,"status",status,"jobId",job);}));}
 public Object jobs(Actor a,String id){access.requireAdmin(a);return db.list("SELECT id,kind,target_id AS targetId,status,stage,attempt,error_code AS errorCode,lease_epoch AS leaseEpoch FROM job WHERE tenant_id=:t"+(id==null?"":" AND id=:id")+" ORDER BY created_at DESC LIMIT 100",Db.params("t",a.tenantId(),"id",id));}
 public Object controlJob(Actor a,String id,boolean cancel){access.requireAdmin(a);return access.write(a,()->tx.execute(s->{var j=db.one("SELECT * FROM job WHERE tenant_id=:t AND id=:id FOR UPDATE",Db.params("t",a.tenantId(),"id",id));String state=j.get("status").toString();if(cancel){if(!Set.of("COMPLETED","FAILED","CANCELLED").contains(state))db.exec("UPDATE job SET status='CANCELLED',cancel_requested_at=UTC_TIMESTAMP(6),lease_epoch=lease_epoch+1 WHERE tenant_id=:t AND id=:id",Db.params("t",a.tenantId(),"id",id));}else{if(!Set.of("FAILED","CANCELLED").contains(state))throw new ApiException(409,"INVALID_STATE","任务当前不可重试");db.exec("UPDATE job SET status='QUEUED',cancel_requested_at=NULL,error_code=NULL,attempt=0,available_at=UTC_TIMESTAMP(6),lease_epoch=lease_epoch+1 WHERE tenant_id=:t AND id=:id",Db.params("t",a.tenantId(),"id",id));}identity.audit(a,cancel?"JOB_CANCEL":"JOB_RETRY","JOB",id);return jobs(a,id);}));}
 public Object accept(Actor a,String build,Map<String,Object> body){access.requireAdmin(a);String reason=IdentityService.required(body,"reason",2000);var b=db.one("SELECT document_id,status FROM index_build WHERE tenant_id=:t AND id=:b",Db.params("t",a.tenantId(),"b",build));return access.guard(a,List.of(b.get("document_id").toString()),()->tx.execute(s->{if(!b.get("status").equals("NEEDS_REVIEW"))throw new ApiException(409,"INVALID_STATE","构建不在待审查状态");db.exec("UPDATE index_build SET review_reason=:r,status='CHUNKING' WHERE tenant_id=:t AND id=:b",Db.params("r",reason,"t",a.tenantId(),"b",build));db.exec("UPDATE job SET status='QUEUED',stage='CHUNKING',available_at=UTC_TIMESTAMP(6) WHERE tenant_id=:t AND target_id=:b AND kind='INGEST' AND status='NEEDS_REVIEW'",Db.params("t",a.tenantId(),"b",build));identity.audit(a,"WARNINGS_ACCEPTED","BUILD",build);return Map.of("buildId",build,"status","QUEUED");}));}
}
